import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor triu_matmul(torch::Tensor A, torch::Tensor B);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

// Computes C = triu(A @ B) for square NxN row-major upper-triangular matrices A, B.
// Exploits triangular structure:
//  - Output tile (bi,bj) with bi > bj is entirely below the diagonal -> skip (C pre-zeroed).
//  - For a tile (bi,bj) with bi <= bj, only k-tiles overlapping [bi*128, bj*128+127] contribute,
//    since A(i,k)=0 for k<i and B(k,j)=0 for k>j.
//  - Only diagonal tiles (bi==bj) need per-element masking; off-diagonal upper tiles are fully valid.
template <class T>
__global__ static void
triu_matmul_kernel(int N, T const* A, T const* B, T* C)
{
  int bi = blockIdx.x;
  int bj = blockIdx.y;
  if (bi > bj) {
    // Fully lower-triangular tile: write zeros directly instead of relying on
    // a costly full-tensor zero-init kernel launched from the host.
    int row_base = bi * 128;
    int col_base = bj * 128;
    for (int idx = threadIdx.x; idx < 128 * 128; idx += blockDim.x) {
      int r = idx / 128;
      int c = idx % 128;
      C[(row_base + r) * N + (col_base + c)] = T(0);
    }
    return;
  }

  // Logical views:
  //  mA: (M,K) row-major
  //  mB: (N,K) which is a transposed logical view of the physically (K,N) row-major B
  //  mC: (M,N) row-major
  Tensor mA = make_tensor(make_gmem_ptr(A), make_shape(N, N), make_stride(N, Int<1>{}));
  Tensor mB = make_tensor(make_gmem_ptr(B), make_shape(N, N), make_stride(Int<1>{}, N));
  Tensor mC = make_tensor(make_gmem_ptr(C), make_shape(N, N), make_stride(N, Int<1>{}));

  auto cta_tiler = make_shape(Int<128>{}, Int<128>{}, Int<8>{});
  auto cta_coord = make_coord(bi, bj, _);
  Tensor gA = local_tile(mA, cta_tiler, cta_coord, Step<_1, X, _1>{});
  Tensor gB = local_tile(mB, cta_tiler, cta_coord, Step<X, _1, _1>{});
  Tensor gC = local_tile(mC, cta_tiler, cta_coord, Step<_1, _1, X>{});

  __shared__ T smemA[128 * 8];
  __shared__ T smemB[128 * 8];
  Tensor sA = make_tensor(make_smem_ptr(smemA), make_shape(Int<128>{}, Int<8>{}));
  Tensor sB = make_tensor(make_smem_ptr(smemB), make_shape(Int<128>{}, Int<8>{}));

  auto tA = make_layout(make_shape(Int<32>{}, Int<8>{}));
  auto tB = make_layout(make_shape(Int<32>{}, Int<8>{}));
  auto tC = make_layout(make_shape(Int<16>{}, Int<16>{}));

  Tensor tAgA = local_partition(gA, tA, threadIdx.x);
  Tensor tAsA = local_partition(sA, tA, threadIdx.x);
  Tensor tBgB = local_partition(gB, tB, threadIdx.x);
  Tensor tBsB = local_partition(sB, tB, threadIdx.x);

  Tensor tCsA = local_partition(sA, tC, threadIdx.x, Step<_1, X>{});
  Tensor tCsB = local_partition(sB, tC, threadIdx.x, Step<X, _1>{});
  Tensor tCgC = local_partition(gC, tC, threadIdx.x, Step<_1, _1>{});

  Tensor tCrC = make_tensor_like(tCgC);
  clear(tCrC);

  // Only iterate over k-tiles that can have nonzero contributions.
  int k_tile_min = bi * 16;      // 128/8 = 16 k-tiles per block-row
  int k_tile_max = bj * 16 + 15; // inclusive

  for (int k_tile = k_tile_min; k_tile <= k_tile_max; ++k_tile) {
    copy(tAgA(_, _, k_tile), tAsA);
    copy(tBgB(_, _, k_tile), tBsB);
    __syncthreads();

    gemm(tCsA, tCsB, tCrC);
    __syncthreads();
  }

  if (bi == bj) {
    int base = bi * 128;
    int r = threadIdx.x % 16;
    int c = threadIdx.x / 16;
    CUTE_UNROLL
    for (int i = 0; i < size<0>(tCrC); ++i) {
      int row = base + r + i * 16;
      CUTE_UNROLL
      for (int j = 0; j < size<1>(tCrC); ++j) {
        int col = base + c + j * 16;
        if (row > col) {
          tCrC(i, j) = T(0);
        }
      }
    }
  }

  copy(tCrC, tCgC);
}

torch::Tensor triu_matmul(torch::Tensor A, torch::Tensor B) {
  TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
  TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D");
  TORCH_CHECK(A.scalar_type() == at::kFloat && B.scalar_type() == at::kFloat,
              "Expect float32 tensors");
  TORCH_CHECK(A.size(0) == A.size(1), "A must be square");
  TORCH_CHECK(B.size(0) == B.size(1), "B must be square");
  TORCH_CHECK(A.size(0) == B.size(0), "A and B must have matching size");

  int N = (int)A.size(0);
  TORCH_CHECK(N % 128 == 0, "N must be a multiple of 128 for this kernel");

  auto A_c = A.contiguous();
  auto B_c = B.contiguous();
  auto C = torch::empty({N, N}, A.options());

  dim3 block(256);
  dim3 grid(N / 128, N / 128);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  triu_matmul_kernel<float><<<grid, block, 0, stream>>>(
      N, A_c.data_ptr<float>(), B_c.data_ptr<float>(), C.data_ptr<float>());

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "triu_matmul_kernel launch failed: ", cudaGetErrorString(err));

  return C;
}
"""

triu_matmul_ext = load_inline(
    name="cute_triu_matmul_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["triu_matmul"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
